'use strict';
const $=s=>document.querySelector(s), windows=$('#windows'),tasks=$('#tasks');let topZ=10,active=null;const opened=new Map();
const photos={hoppaz:[['map-discovery','Discover Lagos on the map'],['community-room','Step into the 360Playlist community room'],['profile-and-progression','Identity, XP, streaks, and collectibles'],['event-discovery','Find your next night out']],adtivity:[['business-overview-masked','Business overview'],['marketing-masked','Product landing page'],['cohort-retention-masked','Cohort retention'],['click-analytics-masked','Click analytics'],['session-replay-masked','Session replay'],['engagement-masked','Engagement analytics'],['revenue-masked','Revenue reporting'],['error-tracking-masked','Error tracking'],['regional-analytics-masked','Regional analytics'],['user-journeys-masked','User journeys'],['pricing-masked','Pricing and plans']],access:[['oxygen-homepage','OxygenX — public product website'],['oxygen-products','OxygenX — product offerings'],['oxygen-investment-overview','OxygenX — investment overview']]};
const projects={adtivity:{name:'Adtivity',role:'CTO & Founder',period:'2020 — Present',category:'Analytics & SaaS',lead:'From event collection to product insight.',description:'A data collection and analytics product that helps founders understand how people use their products. I built the frontend, backend, and SDK.',stack:'React · Next.js · TypeScript · Node.js · SDK development',url:'https://adtivity.xyz',detail:['Built the frontend, backend, and collection SDK, taking ownership across the product.','Developed a library of 40+ typed, documented UI components and real-time analytics dashboards.','Integrated Paystack checkout, subscription access, and asynchronous payment-status reconciliation.','Added Jest and React Testing Library coverage, plus Playwright tests for signup, payment, and dashboard journeys in GitHub Actions.'],notes:'The interesting engineering sits between collection and insight: an SDK that captures events, backend processing, and interfaces that make the resulting data useful. The case study covers my work across those layers.',imageNote:'Data masked for portfolio. These AI-edited derivatives hide operational data and may differ from the original interface.'},access:{name:'Access Group',role:'Frontend Engineer · OxygenX',period:'July 2024 — Present',category:'Lending & Financial Services',lead:'Engineering the workflows behind lending.',description:'At OxygenX, within the Access family, I work on underwriting and customer engagement platforms, including internal workflows for SME and buyback loans.',stack:'React · TypeScript · Next.js · RTK Query · Tailwind CSS · Ant Design',detail:['Built underwriting and customer engagement platform experiences supporting lending operations.','Delivered supervisor-review interfaces with in-app PDF preview and download.','Implemented token refresh, role-based UI access, optimistic updates, and complete loading and error states.','Used route-level code splitting, lazy loading, and bundle analysis to maintain interactive load below two seconds on key surfaces, as reported in my CV.'],notes:'My contribution is focused on internal lending, underwriting, and customer engagement platforms. The supplied screenshots show the public OxygenX website for company context; they are not screenshots of the internal tools.',imageNote:'Company context: public OxygenX website. My work described here focuses on internal platforms.'},hoppaz:{name:'Hoppaz',role:'Full-Stack Engineer',period:'2026 — Present',category:'Events & Communities',lead:'Discover your next event. Find your people.',description:'A Lagos events and community platform combining nearby-event discovery, ticketing, social spaces, and playful progression. I built the frontend and backend and own production delivery.',stack:'Next.js · TypeScript · Supabase / Postgres · LiveKit · Vercel',url:'https://hoppaz.fun',detail:['Own frontend, backend, database, and production deployments for a platform with 1,000+ users, as reported in my CV.','Built guest-to-account conversion that preserves identity and earned progress, alongside email/password and Google sign-in.','Built Speed Meet: interest-based, four-minute voice conversations using LiveKit, a Postgres matching queue, mutual opt-in, and block/report controls.','Created an idempotent event-import pipeline with dry runs, venue pinning, multi-day expansion, image processing, and duplicate matching.'],notes:'For real-time matching, the experience spans an interest picker, waiting state, live voice room with countdown, and mutual keep-in-touch decision. A server-side token route restricts each audio room to its two matched participants. The screenshots also show map discovery, community rooms, and progression.',imageNote:'Real product screenshots supplied by me.'},mysme:{name:'MySMEApp',role:'Frontend Developer · Ecobank via Codemanina',period:'July 2023 — February 2024',category:'Business Banking',lead:'Business banking across borders.',description:'Frontend engineering for Ecobank’s MySME business-banking platform, serving 5,000+ users across 30+ African markets, as reported in my CV.',stack:'React · TypeScript · Next.js · React Hook Form · SCSS',url:'https://mysme.ecobank.com',detail:['Shipped onboarding, account, and payment experiences.','Implemented accessible interfaces with keyboard support, semantic HTML, and clear form validation.','Collaborated with product, design, and backend teams through market-release QA.','Validated journeys in Chrome, Safari, Firefox, and Edge.'],notes:'My work focused on frontend delivery, accessible forms, and consistency across browser and market-release journeys.'},bankit:{name:'Bankit',role:'Frontend Engineer',period:'Selected project',category:'Fintech',lead:'Frontend engineering for financial products.',description:'A fintech application where I contributed to the frontend.',stack:'Frontend engineering',detail:['Worked on the frontend of the fintech application.'],notes:'More project details and screenshots will be added to this case study.'},simfy:{name:'Simfy',role:'Frontend Developer',period:'May — December 2024',category:'Crypto & Trading',lead:'Real-time interfaces for trading and wallets.',description:'Frontend engineering for a crypto application, with some backend contributions.',stack:'React · TypeScript · Redux · WebSockets',detail:['Built trading and wallet interfaces with streaming prices and order-book data.','Implemented transaction confirmations and address and amount validation.','Delivered precision-aware withdrawal experiences.','Contributed to a small portion of the backend.'],notes:'The frontend work combines real-time data with transaction states and careful numeric validation.'}};
const labels={minesweeper:'Minesweeper',welcome:'Welcome to my computer',projects:'My Projects',gallery:'My Pictures',about:'About Olayiwola',skills:'System Properties',resume:'My Résumé',contact:'Contact Me',trash:'Recycle Bin'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function button(key,label,cls='xp-button'){return `<button class="${cls}" data-open="${key}">${label}</button>`}
function shot(group,index=0,cls=''){const p=photos[group][index];return `<div class="shot ${group!=='adtivity'?'raw':''} ${cls}"><img src="assets/${group}/${p[0]}.png" alt="${esc(p[1])}" loading="lazy"></div>`}
function featured(){return `<div class="featured">${['adtivity','access','hoppaz'].map(k=>`<button data-open="${k}"><span class="icon folder" aria-hidden="true"></span><b>${projects[k].name}</b><small>${projects[k].category}</small></button>`).join('')}</div>`}
function galleryItems(group){return photos[group].map((p,i)=>`<button class="thumb" data-view="${group}" data-index="${i}">${shot(group,i)}<b>${esc(p[1])}</b><small>${group==='adtivity'?'Data masked':group==='access'?'Company context':'Product screenshot'}</small></button>`).join('')}
function projectPage(key,tab='overview'){const p=projects[key];return `<div class="project-head"><div class="eyebrow">${esc(p.category.toUpperCase())}</div><h1>${p.name}</h1><p>${esc(p.role)} · ${p.period}</p></div><div class="tabbar" role="tablist" aria-label="${p.name} sections">${['overview','screenshots','engineering'].filter(t=>t!=='screenshots'||photos[key]).map(t=>`<button role="tab" aria-selected="${tab===t}" data-tab="${t}" data-project="${key}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div role="tabpanel">${tab==='overview'?`<h2>${p.lead}</h2><p>${p.description}</p><div class="fact-line"><strong>My role:</strong> ${p.role}<br><strong>Tools:</strong> ${p.stack}</div>${photos[key]?`<button class="project-cover" data-view="${key}" data-index="0" aria-label="Enlarge ${p.name} screenshot">${shot(key)}</button><div class="image-caption">${p.imageNote}</div>`:''}<h3>What I built</h3><ul class="case-bullets">${p.detail.map(x=>`<li>${x}</li>`).join('')}</ul>${p.url?`<a class="xp-button" href="${p.url}" target="_blank" rel="noopener noreferrer">Visit ${p.name} ↗</a>`:''}${button('contact','Discuss a project like this')}`:tab==='screenshots'?`<div class="image-caption">${p.imageNote}</div><div class="gallery-grid">${galleryItems(key)}</div>`:`<h2>Behind the interface</h2><p>${p.notes}</p><ul class="case-bullets">${p.detail.map(x=>`<li>${x}</li>`).join('')}</ul>`}</div>`}
function page(key){if(key==='minesweeper')return `<iframe class="game-frame" title="${labels[key]}" src="games/${key}.html"></iframe>`;if(projects[key])return projectPage(key);switch(key){case'welcome':return `<div class="welcome-heading"><div class="avatar">OA</div><div><div class="eyebrow">OLAYIWOLA'S PERSONAL COMPUTER</div><h1>Hi, I'm Olayiwola.</h1><div class="role">Software engineer. Product builder. CTO.</div></div></div><section class="intro"><h2>I build the whole thing.</h2><p>From the interface people use to the SDKs and backend systems that power it. I'm the CTO and founder of <strong>Adtivity</strong>, and I build lending platforms at <strong>Access Group (OxygenX)</strong>.</p><p>This desktop is a little collection of things I've built, learned, and shipped. Open a folder. Have a look around.</p>${button('projects','Explore my work →','xp-button primary')}${button('contact',"Let's talk")}</section><div class="section-heading"><span>SELECTED WORK</span><span>3 folders</span></div>${featured()}<div class="welcome-bottom"><span class="dot"></span>React · Next.js · Node.js · Python<span class="note">Lagos, Nigeria · Make yourself at home.</span></div>`;
case'projects':return `<div class="eyebrow">C:\\OLAYIWOLA\\MY PROJECTS</div><h1>Things I've built.</h1><p>From startup ownership to financial platforms. Open a project to see my contribution.</p><div class="project-list">${Object.entries(projects).map(([k,p])=>`<button class="project-tile" data-open="${k}"><span class="project-letter">${p.name[0]}</span><h3>${p.name}</h3><p>${p.category}</p><small>${p.role}　↗</small></button>`).join('')}</div>`;
case'gallery':return `<div class="eyebrow">MY PICTURES</div><h1>A closer look.</h1><p>Real interfaces from the products I've worked on. Select any image to open the picture viewer.</p>${['hoppaz','adtivity','access'].map(k=>`<h3>${projects[k].name}${k==='access'?' — Company context':''}</h3>${k==='adtivity'?'<p class="image-caption">Operational data is masked. These are AI-edited derivatives.</p>':''}<div class="gallery-grid">${galleryItems(k)}</div>`).join('')}`;
case'about':return `<div class="welcome-heading"><div class="avatar">OA</div><div><div class="eyebrow">A LITTLE ABOUT ME</div><h1>Olayiwola Agbaje</h1><div class="role">Software Engineer · Lagos, Nigeria</div></div></div><div class="intro"><h2>I like taking ideas all the way.</h2><p>I'm a software engineer with 6+ years of experience building financial and SaaS products. My work spans polished interfaces, reusable frontend systems, SDKs, and backend delivery.</p><p>I care about the details that make products usable: clear states, accessible interactions, performance, and the systems that keep everything working.</p></div><h2>Where I've been</h2><div class="timeline">${[['Access Group (OxygenX)','Frontend Engineer','Jul 2024 — Present','Lending, underwriting, customer engagement, and financial interfaces.'],['Adtivity','CTO & Founder','2020 — Present','Frontend, backend, SDK, analytics, payments, and product delivery.'],['Hoppaz','Full-Stack Engineer','2026 — Present','An events and community product, from database to deployment.'],['Simfy Crypto Exchange','Frontend Developer','May — Dec 2024','Real-time trading and wallet experiences.'],['Ecobank, via Codemanina','Frontend Developer','Jul 2023 — Feb 2024','Business banking experiences across African markets.'],['GeekRadius','Frontend Developer','Nov 2018 — Apr 2020','Four client web applications, from design handoff through deployment.']].map(x=>`<section class="experience"><h3>${x[0]}</h3><small>${x[1]} · ${x[2]}</small><p>${x[3]}</p></section>`).join('')}</div><h3>Education</h3><p>B.Sc., University of Lagos · 2016–2021<br>Front End Development Libraries · freeCodeCamp</p>${button('resume','Open my résumé')}${button('contact','Get in touch')}`;
case'skills':return `<div class="system-head"><span class="icon monitor" aria-hidden="true"></span><div><div class="eyebrow">SYSTEM PROPERTIES</div><h1>Built to build.</h1><div class="role">Olayiwola Agbaje · Software Engineer</div></div></div>${[['Frontend',['React','Next.js','TypeScript','JavaScript','HTML & CSS','SCSS','Tailwind CSS','Ant Design']],['Backend & languages',['Node.js','Python','Rust — intermediate','Supabase / Postgres']],['Architecture & real-time',['SDK development','REST APIs','WebSockets','LiveKit / WebRTC','Redux Toolkit','RTK Query','React Query','Authentication flows']],['Quality & delivery',['Jest','React Testing Library','Playwright','Cypress','GitHub Actions','Git','Code review','Figma handoff']]].map(([h,a])=>`<section class="skills-section"><h3>${h}</h3><div class="skill-tags">${a.map(x=>`<span>${x}</span>`).join('')}</div></section>`).join('')}<div class="system-detail"><strong>Engineering focus</strong><br>Accessible interfaces · reusable component systems · performance · responsive design · end-to-end delivery</div>`;
case'resume':return `<div class="eyebrow">MY DOCUMENTS</div><h1>My résumé.</h1><p>A detailed look at my frontend engineering experience and the products I've helped build.</p><a class="xp-button primary" href="assets/olayiwola-agbaje-resume.pdf" download>Download résumé ↓</a><a class="xp-button" href="assets/olayiwola-agbaje-resume.pdf" target="_blank" rel="noopener">Open PDF ↗</a><p class="image-caption">The supplied résumé focuses on frontend engineering. My portfolio also covers my CTO, backend, and SDK work.</p><object class="resume-view" data="assets/olayiwola-agbaje-resume.pdf" type="application/pdf"><p>Your browser can open the résumé using the link above.</p></object>`;
case'contact':return `<div class="eyebrow">NEW MESSAGE</div><h1>Let's build something.</h1><p>Have a product idea, an engineering challenge, or a role that sounds like a fit? I'd like to hear about it.</p><h3>To: Olayiwola Agbaje</h3><p class="contact-email">agbajeolaiwola@gmail.com</p><a class="xp-button primary" href="mailto:agbajeolaiwola@gmail.com?subject=Let%27s%20build%20something">Write an email ↗</a><button class="xp-button" id="copy-email">Copy email address</button><div class="contact-note">For clients: tell me about the product, the problem, and what you want to build.<br><br>For employers: share the role, the team, and the kind of engineering work involved.</div>${button('projects','Browse my work')}${button('resume','View résumé')}`;
case'trash':return `<div class="eyebrow">RECYCLE BIN</div><div class="empty"><span class="icon bin" aria-hidden="true">♻</span><h2>Some ideas take a detour.</h2><p>This is where abandoned projects and experiments will live — what I tried, why I shelved them, and what I learned.</p><small>The bin is empty for now.<br>There are still plenty of shipped projects to explore.</small><div style="margin-top:20px">${button('projects','Open My Projects')}</div></div>`;default:return''}}
function focus(key){const r=opened.get(key);if(!r)return;r.el.hidden=false;r.el.style.zIndex=++topZ;active=key;opened.forEach((x,k)=>{x.el.classList.toggle('inactive',k!==key);x.task.classList.toggle('active',k===key)});}
function close(key){const r=opened.get(key);if(!r)return;r.el.remove();r.task.remove();opened.delete(key);const remaining=[...opened.keys()];if(remaining.length)focus(remaining.at(-1));else active=null;$('#live').textContent='Window closed';}
function open(key){$('#start-menu').hidden=true;$('#start').setAttribute('aria-expanded','false');if(opened.has(key)){focus(key);return}const title=projects[key]?.name||labels[key]||'Pictures';const el=document.createElement('section');el.className='window'+(key==='minesweeper'?' game-window':'');el.dataset.key=key;el.setAttribute('role','dialog');el.setAttribute('aria-label',title);let offset=(opened.size%4)*22;el.style.transform='none';if(innerWidth>700){el.style.left=`calc(${innerWidth>1200?'18%':'15%'} + ${offset}px)`;el.style.top=`calc(6% + ${offset}px)`}el.innerHTML=`<header class="titlebar"><div class="win-title"><span class="tinyicon" aria-hidden="true"></span><span>${esc(title)}</span></div><div class="window-controls"><button data-window="min" aria-label="Minimize ${esc(title)}">_</button><button data-window="max" aria-label="Maximize ${esc(title)}">□</button><button class="close" data-window="close" aria-label="Close ${esc(title)}">×</button></div></header><div class="menubar" aria-hidden="true"><span><u>F</u>ile</span><span><u>E</u>dit</span><span><u>V</u>iew</span><span>F<u>a</u>vorites</span><span><u>T</u>ools</span><span><u>H</u>elp</span></div><div class="toolbar"><button data-open="welcome"><span class="back-arrow">←</span> Home</button><button data-open="projects"><span class="back-arrow">↑</span></button><span class="divider"></span><button data-open="projects">▰ Folders</button><button data-open="gallery">▧ Pictures</button><span class="divider"></span><span aria-hidden="true">▦ ▾</span></div><div class="address"><span>Address</span><div>📂 C:\\Olayiwola\\${esc(title)}</div><b aria-hidden="true">➜</b></div><div class="explorer"><aside class="sidebar"><div class="side-box"><h3>Portfolio Tasks　⌃</h3><button data-open="projects">▰ View my projects</button><button data-open="gallery">▧ Browse pictures</button><button data-open="resume">▤ Read my résumé</button><button data-open="contact">✉ Contact me</button></div><div class="side-box"><h3>Other Places　⌃</h3><button data-open="welcome">My Computer</button><button data-open="about">About Olayiwola</button><button data-open="skills">System Properties</button></div><div class="side-box"><h3>Details　⌃</h3><p><strong>Olayiwola Agbaje</strong><br>Software Engineer<br>CTO, Adtivity</p><p>Lagos, Nigeria</p></div></aside><main class="content">${page(key)}</main></div><footer class="statusbar"><span>${key==='projects'?'6 projects':title}</span><span>My Computer</span></footer>`;windows.append(el);const task=document.createElement('button');task.textContent='▣ '+title;task.setAttribute('aria-label','Restore or minimize '+title);task.onclick=()=>{if(active===key&&!el.hidden){el.hidden=true;task.classList.remove('active');active=null}else focus(key)};tasks.append(task);opened.set(key,{el,task});focus(key);$('#live').textContent=title+' opened';el.addEventListener('pointerdown',()=>focus(key));el.querySelectorAll('[data-window]').forEach(b=>b.onclick=()=>{const action=b.dataset.window;if(action==='close')close(key);else if(action==='min'){el.hidden=true;task.classList.remove('active');active=null}else{el.classList.toggle('maximized');b.setAttribute('aria-label',(el.classList.contains('maximized')?'Restore ':'Maximize ')+title)}});const bar=el.querySelector('.titlebar');let drag=null;bar.onpointerdown=e=>{if(e.target.closest('button')||el.classList.contains('maximized')||innerWidth<=700)return;const b=el.getBoundingClientRect();drag={x:e.clientX-b.left,y:e.clientY-b.top};bar.setPointerCapture(e.pointerId)};bar.onpointermove=e=>{if(!drag)return;el.style.left=Math.max(0,Math.min(innerWidth-90,e.clientX-drag.x))+'px';el.style.top=Math.max(0,Math.min(innerHeight-85,e.clientY-drag.y))+'px'};bar.onpointerup=bar.onpointercancel=()=>drag=null;bar.ondblclick=e=>{if(!e.target.closest('button'))el.classList.toggle('maximized')};}
function view(group,index){const key='viewer';if(!opened.has(key))open(key);const {el,task}=opened.get(key);el.classList.add('viewer');el.style.width=innerWidth>700?'min(1020px,88%)':'';if(innerWidth>700)el.style.left='6%';const p=photos[group][index];el.querySelector('.win-title span:last-child').textContent=p[1]+' — Picture Viewer';task.textContent='▧ '+projects[group].name;el.querySelector('.content').innerHTML=`<img class="viewer-image ${group!=='adtivity'?'raw':''}" src="assets/${group}/${p[0]}.png" alt="${esc(p[1])}"><div class="viewer-nav"><button class="xp-button" data-view="${group}" data-index="${(index-1+photos[group].length)%photos[group].length}" aria-label="Previous image">←</button><span>${index+1} / ${photos[group].length}</span><button class="xp-button" data-view="${group}" data-index="${(index+1)%photos[group].length}" aria-label="Next image">→</button><button class="xp-button" data-open="${group}">Project details</button></div>`;el.querySelector('.statusbar span').textContent=p[1];el.dataset.group=group;el.dataset.index=index;focus(key);}
document.addEventListener('click',async e=>{const opener=e.target.closest('[data-open]');if(opener)open(opener.dataset.open);const img=e.target.closest('[data-view]');if(img)view(img.dataset.view,Number(img.dataset.index));const tab=e.target.closest('[data-tab]');if(tab){const el=opened.get(tab.dataset.project).el;el.querySelector('.content').innerHTML=projectPage(tab.dataset.project,tab.dataset.tab)}if(e.target.closest('#copy-email')){const b=e.target.closest('button');try{await navigator.clipboard.writeText('agbajeolaiwola@gmail.com');b.textContent='Copied!';$('#live').textContent='Email address copied'}catch{b.textContent='Select the email above to copy'}}if(!e.target.closest('.start-menu')&&!e.target.closest('#start')){$('#start-menu').hidden=true;$('#start').setAttribute('aria-expanded','false')}});
$('#start').onclick=()=>{const menu=$('#start-menu');menu.hidden=!menu.hidden;$('#start').setAttribute('aria-expanded',String(!menu.hidden))};$('#show-desktop').onclick=()=>{const visible=[...opened.values()].some(r=>!r.el.hidden);opened.forEach(r=>{r.el.hidden=visible;r.task.classList.toggle('active',false)});active=null};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#start-menu').hidden=true;$('#start').setAttribute('aria-expanded','false');if(active==='viewer')close('viewer')}if(e.altKey&&e.key==='F4'&&active){e.preventDefault();close(active)}if(active==='viewer'&&['ArrowLeft','ArrowRight'].includes(e.key)){const el=opened.get('viewer').el,g=el.dataset.group,i=Number(el.dataset.index);view(g,(i+(e.key==='ArrowRight'?1:-1)+photos[g].length)%photos[g].length)}});function clock(){const now=new Date();$('#clock').textContent=now.toLocaleTimeString('en',{hour:'numeric',minute:'2-digit'});$('#clock').dateTime=now.toISOString()}clock();setInterval(clock,30000);open('welcome');
